Ext._define('judicial.connections.ConnectionLawsuitGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'judicial.connections.ConnectionLawsuitWindow',


    openDocument: function() {
        var selected = this.getSelectionModel().getSelected();
        var width, height, left, top;

        width = (Ext.getBody().getBox().width * 0.9);
        height = (Ext.getBody().getBox().height * 0.9);
        left = screenX + (screen.width / 2) - (width / 2);
        top = (screen.height / 2) - (height / 2);

        var spec = [
            'width=' + width,
            'height=' + height,
            'top=' + top,
            'left=' + left,
            'scrollbars',
            'resizable',
            'status',
            'titlebar'
        ];

        if(this._wndP) this._wndP.close();

        this._wndP = window.open(
            '/athenas/EJudOutCourtLawsuit/viewer/#' + selected.get('lawsuit_connected'),
            'ejud-proccess-connection-' + selected.get('lawsuit'),
            spec.join(', ')
        );

        if(!this._wndP)
            Ext.Msg.show({
                title: 'Abrindo procedimento!',
                msg: 'O bloqueador de popup interceptou a abertura do procedimento!',
                buttons: Ext.Msg.OK,
                icons: Ext.Msg.ERROR
            });
        else
            this._wndP.owner = undefined;
    },

    getOpenProcessAction: function(cfg){
        if(!this._openprocess)
            this._openprocess = Ext._create('Ext.Button', {
                text: 'Abrir Procedimento',
                iconCls: 'icon-judicial icon-ejud-open-proccess',
                scope: this,
                handler: this.openDocument
            });

        return this._openprocess;
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'lawsuit_connected_icons', width: 65, renderer: core.rendererIconGrid},
                    {header: 'Procedimento', dataIndex: 'lawsuit_connected_unicode', id: 'autoExpandColumn'},
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'judicial.connections.ConnectionLawsuitRestful',
    'judicial.connections.ConnectionLawsuitGrid'
);
